upstream web {
    least_conn;
    server 10.0.1.11:8080 max_fails=3 fail_timeout=10s;
    server 10.0.1.12:8080 max_fails=3 fail_timeout=10s;
    server 10.0.1.13:8080 max_fails=3 fail_timeout=10s;
}
server { listen 80; location / { proxy_pass http://web; } }

routes:
  - match: { prefix: "/api" }
    route: { cluster: api, timeout: 2s, retry_policy: { retry_on: "5xx", num_retries: 2 } }
  - match: { prefix: "/static" }
    route: { cluster: static_assets }
  - match: { prefix: "/", headers: [{ name: "content-type", prefix_match: "application/grpc" }] }
    route: { cluster: grpc_backends }
